def face_side(f):
    verts, tris = f.tessellate(0.0002)
    pts = [verts[i] for i in range(0, len(verts), max(1, len(verts)//25))]
    best = None
    for k in (-1,0,1):
        for idx in (0,1,2):
            d = np.mean([dist_pt_face(rot_back(p, k), bf[idx]) for p in pts])
            if best is None or d < best[0]: best = (d, k, names[idx])
    return best

patch_of = {}
